require __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/api_v2.php';$u=api_v2_user('seller_orders');$ctx=api_v2_seller_context($u,'orders');$owner=(int)$ctx['owner_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!setting_bool('mobile_seller_orders_write_enabled',true))api_v2_error('Seller order writes are disabled.',403);$in=api_input();$id=(int)($in['order_id']??0);$status=(string)($in['status']??'');$allowed=['pending'=>['confirmed','cancelled'],'confirmed'=>['processing','cancelled'],'processing'=>['shipped','cancelled'],'shipped'=>['delivered'],'delivered'=>['completed'],'completed'=>[],'cancelled'=>[]];$q=db()->prepare('SELECT status,payment_status FROM store_orders WHERE id=? AND seller_user_id=?');$q->execute([$id,$owner]);$o=$q->fetch();if(!$o)api_v2_error('Order not found.',404);if(!in_array($status,$allowed[$o['status']]??[],true))api_v2_error('Invalid order status transition.',422);if($status==='cancelled'&&$o['payment_status']==='paid')api_v2_error('Paid orders require the dispute/refund workflow before cancellation.',422);db()->prepare('UPDATE store_orders SET status=? WHERE id=? AND seller_user_id=?')->execute([$status,$id,$owner]);api_v2_ok(['updated'=>true,'order_id'=>$id,'status'=>$status],(int)$u['user_id']);}[$page,$per,$off]=api_v2_page();$cnt=db()->prepare('SELECT COUNT(*) FROM store_orders WHERE seller_user_id=?');$cnt->execute([$owner]);$total=(int)$cnt->fetchColumn();$q=db()->prepare("SELECT id,order_number,buyer_user_id,grand_total,payment_method,payment_status,status,customer_name,customer_phone,city_text,created_at FROM store_orders WHERE seller_user_id=? ORDER BY id DESC LIMIT {$per} OFFSET {$off}");$q->execute([$owner]);api_v2_ok(['orders'=>$q->fetchAll(),'meta'=>api_v2_meta($page,$per,$total)],(int)$u['user_id']);
